/// <summary>
/// Extension of the class <c>TAMRebateCreateTrans</c>
/// </summary>
[ExtensionOf(classStr(TAMRebateCreateTrans))]
final class METTAMRebateCreateTrans_Extension
{
}

Method.Source:
/// <summary>
/// Extended this method to consider the 'External sell data' records for the 'Rebate deal transactions'.
/// </summary>
/// <param name = "_contract">TAMRebateCreateTransContract</param>
public static void processRebateTrans(TAMRebateCreateTransContract _contract)
{
    container               con         = _contract.parmPackedRecords();
    RecId                   dealRecId   =  conPeek(con, 1);
    TAMRebateDeal           rebateDeal  = TAMRebateDeal::find(dealRecId);
    FeatureManagementState  featureManagementState;


    select firstonly featureManagementState
        where featureManagementState.Name == METConstants::UnifiedPricingFeature;

    if(featureManagementState.IsEnabled == NoYes::Yes && rebateDeal.METUseExternalSellData == NoYes::Yes)
    {
        TAMRebateCreateTrans::metCreateRebateDateTransactionsForProvision(_contract, rebateDeal);
    }

    next processRebateTrans(_contract);

}

/// <summary>
/// Created for the FSD - CB 201, Rebates Extension - Undertake Build -  External Data Sources
/// </summary>
/// <param name = "_contract">TAMRebateCreateTransContract</param>
/// <param name = "_rebateDeal">TAMRebateDeal</param>
private static void metCreateRebateDateTransactionsForProvision(TAMRebateCreateTransContract _contract, TAMRebateDeal _rebateDeal)
{
    ToDate                      toDate      = _contract.parmToDate();
    FromDate                    fromDate    = _contract.parmFromDate();
    TAMRebateDate               rebateDate;
    TAMRebateTrans              rebateTrans;
    TAMRebateTable              rebateTable;
    TAMRebateDateTrans          rebateDateTrans;
    METRebateScanSupplierTable  externalSellData;

    select firstonly rebateTable
        where rebateTable.RebateDeal == _rebateDeal.RecId;

    while select externalSellData
        where externalSellData.TransactionDate > fromDate
            && externalSellData.TransactionDate < toDate
            && externalSellData.ProvisionPosted == NoYes::No
            && externalSellData.RebatePosted == NoYes::No
    {
        select firstonly rebateTrans
            where rebateTrans.METRebateScanSupplierTable == externalSellData.RecId
                join rebateDateTrans
                where rebateDateTrans.RebateTransId == rebateTrans.RebateTransId
                && rebateDateTrans.RebateTransactionType == _contract.parmRebateTransactionType();

        if (!rebateTrans.RecId)
        {
            select firstonly rebateDate
                where rebateDate.RebateId == rebateTable.RebateId
                && rebateDate.RebateFromDate <= externalSellData.TransactionDate
                && rebateDate.RebateToDate >= externalSellData.TransactionDate;

            if(rebateDate)
            {
                rebateDateTrans = METTAMProcessExternalSellDataHelper::createDateTrans(_rebateDeal.RecId, rebateTable.RebateId, externalSellData.TransactionDate, rebateDate, _contract.parmRebateTransactionType(), externalSellData);

                if(rebateDateTrans.RecId && rebateDateTrans.RebateFromDate <= externalSellData.TransactionDate && rebateDateTrans.RebateToDate >= externalSellData.TransactionDate)
                {
                    rebateTrans = METTAMProcessExternalSellDataHelper::createTrans(rebateDateTrans, rebateDate, externalSellData, rebateTable.UnitId, _rebateDeal.ModuleInventCustVend);
                }
            }
        }
    }

    TAMRebateTrans clearRebateTrans;

    select rebateDateTrans
        where rebateDateTrans.RebateDeal == _rebateDeal.RecId
        notexists join clearRebateTrans
        where rebateDateTrans.RebateTransId == clearRebateTrans.RebateTransId;

    if (rebateDateTrans.RecId)
    {
        ttsbegin;
        rebateDateTrans.delete();
        ttscommit;
    }
}
